75: function addFrame(x,y,z,side,index){const frame=new THREE.Group();frame.position.set(x,y,z);frame.rotation.y=side>0?-Math.PI/2:Math.PI/2;world.add(frame);const w=index%3===0?1.12:.82,h=index%3===0?1.3:1.04;const wood=new THREE.MeshStandardMaterial({color:0x251a13,roughness:.7}),inner=new THREE.MeshStandardMaterial({color:index%2?0x292c25:0x3b3025,roughness:1}),canvas=new THREE.MeshStandardMaterial({color:index%3===0?0x625648:0x312c26,roughness:1});mesh(new THREE.BoxGeometry(w+.12,h+.12,.09),wood,0,0,0,frame);mesh(new THREE.BoxGeometry(w,h,.025),inner,0,0,.057,frame);mesh(new THREE.BoxGeometry(w-.12,h-.12,.018),canvas,0,0,.075,frame);if(index%4===1){const eyes=new THREE.MeshStandardMaterial({color:0xa99c7a,emissive:0x322c1f,emissiveIntensity:.3});for(const ex of [-.13,.13])mesh(new THREE.SphereGeometry(.018,8,6),eyes,ex,.07,.092,frame);}}
