79: function buildHall(){
80:   clearWorld();
81:   floorTex.repeat.set(1,9);wallTex.repeat.set(1.7,1);
82:   mesh(new THREE.PlaneGeometry(6.5,40),mats.floor,0,.005,-1,world).rotation.x=-Math.PI/2;
83:   mesh(new THREE.PlaneGeometry(6.5,40),mats.ceiling,0,4.52,-1,world).rotation.x=Math.PI/2;
84:   // Long repeated walls, seams, floor and crown moulding make the corridor feel built, not tiled.
85:   for(let i=0;i<7;i++){
86:     const z=15.8-i*5.35;
87:     for(const side of [-1,1]){
88:       box(side*3.23,2.25,z, .22,4.5,5.4,mats.wall);
