91:       if(i%2===1)addFrame(side*3.095,2.45,z+.7,side,i+1);
92:       if(i===2||i===5)addSideDoor(side*3.06,z-1.7,side,i);
93:     }
94:     box(0,4.35,z,6.2,.22,.18,mats.trim);
95:   }
96:   // End walls. The front door opens onto another copy of this impossible corridor.
97:   box(0,2.25,18.55,6.5,4.5,.4,mats.wall);
98:   box(0,2.25,-21.0,6.5,4.5,.42,mats.wall);
99:   for(let i=0;i<15;i++){
100:     const x=(Math.random()-.5)*5.5,z=-14+Math.random()*29;
101:     const plank=box(x,.035,z,.18+Math.random()*.42,.035,.025,mats.trim);
