103:   }
104:   for(const z of [-8,3,13]){
105:     // Black windows that show no reflection and no world beyond.
106:     for(const side of [-1,1]){
107:       const g=new THREE.Group();g.position.set(side*3.08,2.25,z);g.rotation.y=side>0?-Math.PI/2:Math.PI/2;world.add(g);
108:       box(0,0,0,.94,1.55,.12,mats.trim,g);box(0,0,.07,.72,1.31,.04,mats.glass,g);
109:       box(0,0,.1,.035,1.3,.04,mats.metal,g);box(0,0,.1,.7,.035,.04,mats.metal,g);
110:       const haze=new THREE.MeshBasicMaterial({color:0x101715,transparent:true,opacity:.35});mesh(new THREE.PlaneGeometry(.68,1.25),haze,0,0,.105,g);
111:     }
