122:   box(-1.18,1.6,.01,.16,3.35,.22,mats.trim,back);box(1.18,1.6,.01,.16,3.35,.22,mats.trim,back);
123:   box(0,1.65,.11,1.1,2.6,.03,mats.dark,back);
